import React, { useEffect, useState } from 'react';
import './Coupons.css'; // CSS fájl importálása

const Coupons = () => {
    const [coupons, setCoupons] = useState([]);
    const [searchTerm, setSearchTerm] = useState(''); // Keresési kifejezés

    useEffect(() => {
        fetch('http://localhost:5000/api/coupons')
            .then(response => response.json())
            .then(data => {
                console.log(data); // Ellenőrizd, hogy itt kapod-e meg a megfelelő adatokat
                setCoupons(data);
            })
            .catch(error => console.error('Error fetching coupons:', error));
    }, []);

    // Szűrési logika
    const filteredCoupons = coupons.filter(coupon =>
        coupon.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        coupon.code.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="app-container">
            <header>
                <h1>Buyitfromchina - Kínábólveddmeg</h1>
                <p>Minden kupon egy helyen azonnal!</p>
                <p>Kuponkereső 1.1.2 beta</p>
                <input
                    type="text"
                    placeholder="Keresés termékre..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="search-input"
                />
            </header>

            <div className="coupons-grid">
                {filteredCoupons.length > 0 ? (
                    filteredCoupons.map((coupon, index) => (
                        <div key={index} className="coupon-container">
                            <img src={coupon.image} alt={coupon.name} className="coupon-image" />
                            <div className="coupon-info">
                                <p className="coupon-title">Név: {coupon.name}</p>
                                <p>Kupon: {coupon.code}</p>
                                <p>Ár: {coupon.price} USD</p>
                                <p>Raktár: {coupon.warehouse}</p>
                                <p>Forrás: {coupon.source}</p>
                                <p>
                                    Link: <a href={coupon.link} target="_blank" rel="noopener noreferrer" className="coupon-link">Megtekintés</a>
                                </p>
                                <button onClick={() => navigator.clipboard.writeText(coupon.code)} className="copy-button">
                                    Kupon másolása
                                </button>
                            </div>
                        </div>
                    ))
                ) : (
                    <p>A legfrissebb kuponok és az árak töltődnek, kis türelmet kérek....</p>
                )}
            </div>

            <footer>
                <p>Minden jog fenntartva, készítő: [Buyitfromchina]</p>
            </footer>
        </div>
    );
};

export default Coupons;
